    'Описание недоступно': '描述不可用',
    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': '最小：游戏与启动器一起关闭。标准：也没有剪贴板、没有其他窗口、没有显示设置。',
    'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': '严格：完整性也较低——仅写入配置文件文件夹，其他所有内容均为只读。不保证每个模组都能工作。',
