    'Виноват мод: {mod}': '造成模式：{mod}',
    'Виноват мод': '由mod引起',
    'Лаунчер не нашёл ни crash-отчёта, ни логов: игра упала до их создания.': '启动器既没有找到崩溃报告也没有找到日志：游戏在创建它们之前就崩溃了。',
    'latest.log заканчивается нормальным выходом игры, стека ошибки нет. Скорее всего, это лог прошлого запуска, а текущее падение не успело в него записаться.': 'latest.log 以正常游戏关闭结束，并且不包含错误堆栈。它可能是以前运行的日志，当前崩溃没有时间写入它。',
    'Игре не хватило выделенной памяти — JVM была убита с OutOfMemoryError.': '游戏耗尽了分配的内存——JVM 因 OutOfMemoryError 被终止。',
    'JVM упала на нативном вызове: {frame}': 'JVM 在本机调用中崩溃：{frame}',
    'Процесс Java завершился аварийно (не обычное исключение).': 'Java 进程异常终止（不是常规异常）。',
    'JVM упала в драйвере видеокарты: {frame}': 'JVM 在 GPU 驱动程序中崩溃：{frame}',
    'JVM упала в нативном коде драйвера видеокарты.': 'JVM 在 GPU 驱动程序本机代码中崩溃。',
    'Мод или загрузчик собраны под другую версию Java. Игра не смогла загрузить классы.': 'mod 或加载器是为不同的 Java 版本构建的。游戏无法加载类。',
    'Мод или загрузчик собраны под другую версию Java. {error}': 'mod 或加载器是为不同的 Java 版本构建的。 {error}',
    'Игра не смогла создать окно/контекст OpenGL.': '游戏无法创建 OpenGL 窗口/上下文。',
    'Набор модов несовместим: чего-то не хватает или версии не совпадают.': '模组集不兼容：缺少某些内容或版本不匹配。',
    'Проблема с модами: {mods}.': '模组问题：{mods}。',
    'Mixin-патч не применился, вероятный виновник — {mod}.': 'Mixin补丁应用失败；罪魁祸首可能是{mod}。',
    'Mixin-патч не применился: мод несовместим с этой версией игры или другого мода.': 'Mixin 补丁无法应用：该模组与该游戏或其他模组版本不兼容。',
    'Отчёт прямо указывает на мод.': '该报告直接指向了一个mod。',
    'Отчёт прямо указывает на мод. {error}': '该报告直接指向了一个mod。 {error}',
    'Судя по стеку, ошибка пришла из {mod}.': '堆栈跟踪指向{mod}。',
    '{error}\n\nСудя по стеку, ошибка пришла из {mod}.': '{error}\n\n堆栈跟踪指向 。',
    'Точную причину определить не удалось — смотрите лог.': '无法确定确切原因 - 检查日志。',
    '{error}\n\nТочную причину определить не удалось — смотрите лог.': '{error}\n\n无法确定确切原因 - 检查日志。',
    'Откройте папку игры и проверьте каталог crash-reports вручную.': '打开游戏文件夹并手动检查崩溃报告目录。',
    'Запустите игру ещё раз — при новом падении отчёт появится здесь.': '再次开始游戏 - 下次崩溃时报告将出现在此处。',
    'Посмотрите консоль лаунчера — ошибка могла остаться только в stderr.': '检查启动器控制台 — 错误可能仅出现在 stderr 中。',
    'Запустите игру снова: при новом падении появится crash-report.': '再次启动游戏：下次崩溃时将出现崩溃报告。',
    'Откройте профиль → «Java и память» и поднимите верхний предел (например, 6144 МБ).': '打开配置文件 →“Java 和内存”并提高上限（例如 6144 MB）。',
    'Не ставьте больше ~70% всей оперативной памяти — станет только хуже.': '不要分配超过总 RAM 的 70% - 这只会让事情变得更糟。',
    'Проверьте, нет ли рядом тяжёлых сборок с сотнями модов.': '检查附近是否有其他包含数百个模组的重型模组包。',
    'Чаще всего это драйвер видеокарты или мод с нативным кодом (шейдеры, рендер).': '最常见的是 GPU 驱动程序或带有本机代码（着色器、渲染）的 mod。',
    'Обновите драйвер видеокарты.': '更新 GPU 驱动程序。',
    'Уберите недавно добавленные моды и запустите снова.': '删除最近添加的模组并重新开始。',
    'Откройте профиль → «Java и память» и выберите версию: 1.16 и ниже — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.': '打开配置文件 →“Java 和内存”并选择版本：1.16 及以下 — Java 8、1.17–1.20.4 — Java 17、1.20.5+ — Java 21。',
    'Если Java нужной версии нет — скачайте её в настройках лаунчера.': '如果缺少所需的 Java 版本，请在启动器设置中下载。',
    'Обновите драйвер видеокарты (NVIDIA/AMD/Intel).': '更新 GPU 驱动程序（NVIDIA/AMD/Intel）。',
    'Проверьте, что видеокарта не отключена и игра не запущена в режиме удалённого рабочего стола.': '确保 GPU 已启用并且游戏未通过远程桌面运行。',
    'Уберите моды рендера/шейдеров, если падение началось после их установки.': '如果安装渲染/着色器模组后开始崩溃，请删除它们。',
    'Прочитайте строки «requires … which is missing» в отчёте — там перечислено, чего не хватает.': '阅读报告中的“需要……缺少的内容”行——它们列出了缺少的内容。',
    'Установите недостающие моды или уберите лишние.': '安装缺少的模组或删除多余的模组。',
    'Проверьте, что все моды одной версии Minecraft.': '确保所有模组都适用于相同的 Minecraft 版本。',
    'Обновите виновный мод до версии под ваш Minecraft.': '将 culprit mod 更新为适合您的 Minecraft 的版本。',
    'Уберите конфликтующий мод или его версию для другой сборки.': '删除另一个模组包的冲突模组或其版本。',
    'Обновите или удалите виновный мод.': '更新或删除罪魁祸首模组。',
    'Проверьте, что его версия совпадает с версией Minecraft.': '确保其版本与 Minecraft 版本匹配。',
    'Обновите виновный мод или удалите его и проверьте запуск.': '更新罪魁祸首 mod 或将其删除并测试启动。',
    'Если не помогло — отключите моды по половине, чтобы найти конфликт.': '如果这没有帮助，请将模组禁用一半以查找冲突。',
    'Откройте отчёт и посмотрите блок «Caused by» — там обычно указан мод.': '打开报告并检查“引起于”块 - 它通常命名模组。',
    'Отключите половину модов и запустите: так конфликт находится быстрее всего.': '禁用一半的模组并启动：这会最快找到冲突。',
