    '.mrpack — стандартный формат Modrinth (моды, конфиги, ресурспаки). .zip — папка сборки для ручной установки.': '.mrpack — 标准 Modrinth 格式（模组、配置、资源包）。 .zip — 用于手动安装的 modpack 文件夹。',
    'Не удалось получить ответ ИИ': '无法获得 AI 响应',
    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена.': '最小：游戏与启动器一起关闭。标准：也没有剪贴板。',
    'Игра запускается в песочнице: мод не может писать за пределами папки профиля. На стандартном и жёстком уровнях он ещё и не может запускать другие программы. Буфер обмена не ограничивается.': '游戏在沙箱中运行：模组无法在配置文件文件夹之外写入。在标准和严格的层面上，它也无法启动其他程序。剪贴板不受限制。',
    'Минимальная: игра в песочнице — не может писать за пределами папки профиля. Стандартная: ещё и не может запускать другие программы.': '最小：游戏在沙箱中运行 - 它不能在配置文件文件夹之外写入。标准：它也无法启动其他程序。',
    'Жёсткая: то же плюс отдельные HOME/APPDATA/TEMP внутри профиля.': '严格：相同加上配置文件内单独的 HOME/APPDATA/TEMP。',
    'ИИ-сборка': '人工智能模组',
    'ИИ-ассистент сборок': 'AI模组助手',
    'Опишите сборку словами — ассистент подберёт моды, ресурс-паки и шейдеры и поставит их в новый профиль.': '用文字描述该包 - 助手选择模组、资源包和着色器并将它们安装到新的配置文件中。',
    'Кнопка «ИИ-сборка» в «Установках»: ассистент подбирает моды, ресурс-паки и шейдеры по описанию и сам скачивает их в новый профиль.': '安装中的“AI modpack”按钮：助手从您的描述中选择模组、资源包和着色器，并将它们下载到新的配置文件中。',
    'Что за сборка?': '什么样的包？',
    'Например: магическая сборка на 1.20.1 для слабого ноутбука, с квестами и без лишнего': '例如：一台性能较弱的笔记本电脑上的 1.20.1 魔法包，带有任务，没有任何额外内容',
