    'Откройте мир для сети (Esc → «Открыть для сети…»), затем друг вводит этот код.': '打开世界到 LAN（Esc→“打开到 LAN...”），然后你的朋友输入此代码。',
    'В Minecraft: Сетевая игра → Прямое подключение → добавьте {a}': '在《我的世界》中：多人游戏→直接连接→添加{a}',
