    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Minimaalinen: peli sulkeutuu yhdessä kantoraketin kanssa. Vakio: ei myöskään leikepöytää, ei muita ikkunoita, ei näyttöasetuksia.',
    'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': 'Tiukka: myös alhainen eheys - kirjoitetaan vain profiilikansioon, kaikki muu on vain luku -tilassa. Ei takaa, että jokainen modi toimii.',
