    'Жёсткая': 'Strict',
    'Моды работают внутри игры, поэтому полной изоляции не бывает. Чем выше уровень, тем меньше мод может сделать в системе.': 'Les mods fonctionnent à l\'intérieur du jeu, donc une isolation complète est impossible. Plus le niveau est élevé, moins un mod peut faire dans le système.',
    'Стандартная: запрет на буфер обмена, чужие окна и настройки экрана. Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение.': 'Standard : pas de presse-papiers, pas d\'autres fenêtres, pas de paramètres d\'affichage. Strict : également faible intégrité : écriture uniquement dans le dossier de profil, tout le reste en lecture seule.',
