    'Описание недоступно': 'La description n\'est pas disponible',
    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Minimal : le jeu se ferme avec le lanceur. Standard : pas de presse-papiers, pas d\'autres fenêtres, pas de paramètres d\'affichage.',
    'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': 'Strict : également faible intégrité : écriture uniquement dans le dossier de profil, tout le reste en lecture seule. Ne garantit pas que chaque mod fonctionnera.',
