    'Сборка готова: {name}': 'Emballage prêt : {name}',
    'Опишите сборку хотя бы одним предложением': 'Décrivez le pack en au moins une phrase',
    'Новая сборка': 'Nouveau pack',
    'Лимит модов': 'Limite de modules',
    'Без ограничения': 'Aucune limite',
    'Источник модов': 'Source du module',
    'Оба сразу': 'Les deux à la fois',
    'Сначала Modrinth': 'Modrinth en premier',
    'Сначала CurseForge': 'CurseForge en premier',
    'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': 'Laissez la limite vide et le pack recevra autant de mods qu\'il en a besoin. « Les deux à la fois » recherche dans les deux catalogues ; celui préféré est recherché en premier, puis l\'autre si rien n\'est trouvé.',
    'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник: «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': 'Limite : le nombre maximum de mods à sélectionner – laissez-le vide pour "autant que le pack en a besoin". Source : « Les deux à la fois » recherche dans les deux catalogues ; celui préféré est recherché en premier, puis l\'autre si rien n\'est trouvé.',
    'Скрывать лаунчер при запуске игры': 'Masquer le lanceur au lancement du jeu',
    'Dracula': 'Dracula',
    'Alucard': 'Alucard',
    'Dracula использует официальную палитру Dracula (тёмная) и Alucard (светлая) — выбранный цвет на неё не влияет.': 'Dracula utilise les palettes officielles Dracula (foncé) et Alucard (clair) — la couleur sélectionnée ne l\'affecte pas.',
    'Дубликаты, версии модов, память, зависимости и Java': 'Doublons, versions de mod, mémoire, dépendances et Java',
    'Столько ОЗУ система не отдаст: оставьте ей хотя бы 1 ГБ, иначе игра вылетит при запуске.': 'Le système ne donnera pas beaucoup de RAM : laissez-lui au moins 1 Go sinon le jeu plantera au lancement.',
    'Для сборок с модами меньше 2 ГБ почти всегда мало — начнутся лаги и вылеты.': 'Pour les packs modifiés de moins de 2 Go, c\'est presque toujours trop peu – attendez-vous à des bégaiements et des plantages.',
    '.mrpack — формат Modrinth: моды скачиваются по ссылкам, конфиги внутри архива. .zip — формат CurseForge (manifest.json + overrides), его понимают CurseForge и Prism.': '.mrpack — le format Modrinth : les mods sont téléchargés par URL, les configurations sont à l\'intérieur. .zip — le format CurseForge (manifest.json + overrides), compris par CurseForge et Prism.',
    'Играть с друзьями': 'Jouez avec des amis',
    'Порт откроет сам роутер по UPnP: свой сервер и сторонние программы не нужны.': 'Le routeur ouvre lui-même le port via UPnP : aucun serveur propre ni aucune application tierce n\'est nécessaire.',
    'Скажите друзьям этот адрес — порт открыт на роутере.': 'Envoyez cette adresse à vos amis : le port est ouvert sur le routeur.',
    'Открыть доступ': 'Accès ouvert',
    'Закрыть доступ': 'Fermer l\'accès',
    'Скопировать': 'Copie',
    'Адрес скопирован': 'Adresse copiée',
    'Скопируйте адрес вручную.': 'Copiez l\'adresse manuellement.',
    'по сети: {a}': 'sur LAN : {a}',
    'Сначала откройте мир для сети: в игре Esc → «Открыть для сети…».': 'Ouvrez d\'abord un monde en LAN : dans le jeu, appuyez sur Echap → "Ouvrir en LAN…".',
    'Другу не нужен белый IP и настройка роутера — просто передайте ему код.': 'Votre ami n\'a besoin d\'aucune adresse IP publique ni de configuration de routeur : envoyez-lui simplement le code.',
    'Остановить канал': 'Arrêtez le tunnel',
    'Код для друга': 'Code pour votre ami',
    'Адрес для Minecraft': 'Adresse pour Minecraft',
    'Код скопирован': 'Code copié',
    'Откройте мир для сети (Esc → «Открыть для сети…»), затем друг вводит этот код.': 'Ouvrez le monde sur LAN (Esc → "Ouvrir sur LAN…"), puis votre ami entre ce code.',
    'В Minecraft: Сетевая игра → Прямое подключение → добавьте {a}': 'Dans Minecraft : Multijoueur → Connexion directe → ajouter {a}',
    'Соединяю…': 'De liaison…',
    'Создать код': 'Créer un code',
    'Подключиться по коду': 'Rejoindre par code',
    'Подключиться': 'Connecter',
    'Через роутер (UPnP)': 'Via le routeur (UPnP)',
    'Скопируйте вручную.': 'Copiez-le manuellement.',
    'Введите код друга': 'Entrez le code de votre ami',
    'Co-op': 'Coopérative',
    'Играйте с друзьями без своего сервера: один создаёт код, другой подключается по нему.': 'Jouez avec des amis sans votre propre serveur : l\'un crée un code, l\'autre s\'y joint.',
    'Сначала создайте профиль.': 'Créez d’abord un profil.',
    'Модель ИИ': 'Modèle d\'IA',
    'Первая доступная': 'Premier disponible',
    'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник и модель выбираются в окне «ИИ-сборка».': 'Limite : le nombre maximum de mods à sélectionner – laissez-le vide pour "autant que le pack en a besoin". La source et le modèle sont choisis dans la fenêtre du pack AI.',
    'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом. Модель — кто именно собирает сборку.': 'Laissez la limite vide et le pack recevra autant de mods qu\'il en a besoin. « Les deux à la fois » recherche dans les deux catalogues ; celui qui est préféré est recherché en premier, puis l\'autre. Le modèle est celui qui construit réellement le pack.',
