    'Моды работают внутри игры, поэтому полной изоляции не бывает. Чем выше уровень, тем меньше мод может сделать в системе.': 'Моды запускаюцца ўнутры гульні, таму поўная ізаляцыя немагчымая. Чым вышэй узровень, тым менш мод можа зрабіць у сістэме.',
    'Стандартная: запрет на буфер обмена, чужие окна и настройки экрана. Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение.': 'Стандарт: без буфера абмену, без іншых вокнаў, без налад адлюстравання. Строгі: таксама нізкая цэласнасць — запіс толькі ў тэчку профілю, усё астатняе толькі для чытання.',
