    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Мінімум: гульня зачыняецца разам з лаунчером. Стандарт: таксама няма буфера абмену, няма іншых вокнаў, няма налад дысплея.',
