    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Минимално: игра се затвара заједно са покретачем. Стандардно: такође нема међуспремника, нема других прозора, нема подешавања екрана.',
    'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': 'Строго: такође низак интегритет — писање само у фасциклу профила, све остало само за читање. Не гарантује да ће сваки мод радити.',
