    'Жёсткая': '厳しい',
    'Моды работают внутри игры, поэтому полной изоляции не бывает. Чем выше уровень, тем меньше мод может сделать в системе.': 'Mod はゲーム内で実行されるため、完全に分離することは不可能です。レベルが高くなるほど、MOD がシステム内でできることは少なくなります。',
    'Стандартная: запрет на буфер обмена, чужие окна и настройки экрана. Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение.': '標準: クリップボードなし、他のウィンドウなし、表示設定なし。厳密: 整合性も低く、プロファイル フォルダーにのみ書き込み、その他は読み取り専用です。',
    'Не гарантирует работу всех модов.': 'すべてのMODが動作することを保証するものではありません。',
