    'Ссылки': 'リンク',
    'Описание': '説明',
    'Описание недоступно': '説明が利用できません',
    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': '最小限: ゲームはランチャーとともに終了します。標準: クリップボードも、他のウィンドウも、表示設定もありません。',
    'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': '厳密: 整合性も低く、プロファイル フォルダーにのみ書き込み、その他は読み取り専用です。すべてのMODが動作することを保証するものではありません。',
    'Игра закрылась с ошибкой': 'ゲームがクラッシュした',
    'Код выхода: {code}. Подробности — в crash-логе игры.': '終了コード: {code}。詳細については、ゲームのクラッシュ ログを参照してください。',
    'Открыть папку игры': 'ゲームフォルダを開く',
    'Понятно': 'わかった',
    'Вход через LittleSkin': 'LittleSkin でサインインする',
    'Аккаунт LittleSkin — логин и пароль.': 'LittleSkin アカウント — ログインとパスワード。',
    'Удалить аккаунт?': 'アカウントを削除しますか?',
    'Аккаунт {name} будет удалён с этого компьютера.': 'アカウント {name} はこのコンピュータから削除されます。',
    'Модпаки': 'モッドパック',
