    'Коротко': 'まとめ',
    'О чём эта сборка': 'このMODパックは何についてのものですか',
    'Полное описание: моды, настройки, для кого сборка': '完全な説明: MOD、設定、対象者',
    'Проверка сборки': 'Modpackのチェック',
