    'Импорт из Modrinth App': 'Modrinth アプリからインポート',
    'Моды, конфиги и миры профиля скопируются в новый профиль лаунчера.': 'プロファイルの MOD、構成、およびワールドが新しいランチャー プロファイルにコピーされます。',
    'Ищу профили…': 'プロフィールを探しています…',
    'Профили Modrinth App не найдены.': 'Modrinth アプリのプロファイルが見つかりません。',
    'модов: {n}': '改造: {n}',
    'модов': '改造',
    'конфигов': '構成',
    'размер': 'サイズ',
    'выключено': '無効',
    'Автор': '著者',
    'Сохранить': '保存',
    '.mrpack — стандартный формат Modrinth (моды, конфиги, ресурспаки). .zip — папка сборки для ручной установки.': '.mrpack — 標準 Modrinth 形式 (mod、config、リソース パック)。 .zip — 手動インストール用の modpack フォルダー。',
    'Не удалось получить ответ ИИ': 'AIの応答が得られませんでした',
    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена.': '最小限: ゲームはランチャーとともに終了します。標準: クリップボードもありません。',
    'Игра запускается в песочнице: мод не может писать за пределами папки профиля. На стандартном и жёстком уровнях он ещё и не может запускать другие программы. Буфер обмена не ограничивается.': 'ゲームはサンドボックス内で実行されます。MOD はプロファイル フォルダーの外に書き込むことはできません。標準および厳密レベルでは、他のプログラムを起動することもできません。クリップボードには制限がありません。',
    'Минимальная: игра в песочнице — не может писать за пределами папки профиля. Стандартная: ещё и не может запускать другие программы.': '最小限: ゲームはサンドボックス内で実行されます。プロファイル フォルダーの外に書き込むことはできません。標準: 他のプログラムも起動できません。',
    'Жёсткая: то же плюс отдельные HOME/APPDATA/TEMP внутри профиля.': '厳密: 同じものに加えて、プロファイル内の別の HOME/APPDATA/TEMP。',
    'ИИ-сборка': 'AI モッドパック',
    'ИИ-ассистент сборок': 'AI modpack アシスタント',
    'Опишите сборку словами — ассистент подберёт моды, ресурс-паки и шейдеры и поставит их в новый профиль.': 'パックを言葉で説明します。アシスタントは MOD、リソース パック、シェーダーを選択し、新しいプロファイルにインストールします。',
    'Кнопка «ИИ-сборка» в «Установках»: ассистент подбирает моды, ресурс-паки и шейдеры по описанию и сам скачивает их в новый профиль.': '[インストール] の [AI modpack] ボタン: アシスタントは説明から MOD、リソース パック、シェーダーを選択し、新しいプロファイルにダウンロードします。',
    'Что за сборка?': 'どのようなパックですか？',
    'Например: магическая сборка на 1.20.1 для слабого ноутбука, с квестами и без лишнего': '例: 弱いラップトップ上の 1.20.1 用のマジック パック (クエストのみで追加のものは何もありません)',
