    'Сначала CurseForge': 'まずはCurseForge',
    'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': '制限を空のままにしておくと、パックに必要な数の MOD が追加されます。 「両方を一度に」は両方のカタログを検索します。優先されるものが最初に検索され、何も見つからない場合は次にもう一方が検索されます。',
    'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник: «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': '制限: 選択する MOD の最大数 — 「パックに必要な数だけ」空のままにしておきます。出典: 「両方を一度に」は両方のカタログを検索します。優先されるものが最初に検索され、何も見つからない場合は次にもう一方が検索されます。',
