    'Dracula использует официальную палитру Dracula (тёмная) и Alucard (светлая) — выбранный цвет на неё не влияет.': 'Dracula は公式の Dracula (ダーク) および Alucard (ライト) パレットを使用します。選択した色は影響しません。',
    'Дубликаты, версии модов, память, зависимости и Java': '重複、MOD バージョン、メモリ、依存関係、および Java',
    'Столько ОЗУ система не отдаст: оставьте ей хотя бы 1 ГБ, иначе игра вылетит при запуске.': 'システムはそれほど多くの RAM を提供しません。少なくとも 1 GB のままにしておかないと、起動時にゲームがクラッシュします。',
    'Для сборок с модами меньше 2 ГБ почти всегда мало — начнутся лаги и вылеты.': 'MOD 入りパックの場合、2 GB 未満ではほとんどの場合少なすぎます。途切れやクラッシュが発生することが予想されます。',
    '.mrpack — формат Modrinth: моды скачиваются по ссылкам, конфиги внутри архива. .zip — формат CurseForge (manifest.json + overrides), его понимают CurseForge и Prism.': '.mrpack — Modrinth 形式: MOD は URL によってダウンロードされ、設定はその中にあります。 .zip — CurseForge および Prism で理解される CurseForge 形式 (manifest.json + オーバーライド)。',
    'Играть с друзьями': '友達と遊ぶ',
