    'Сначала откройте мир для сети: в игре Esc → «Открыть для сети…».': 'まずワールドを LAN に開きます。ゲーム内で Esc → 「LAN に開く…」を押します。',
    'Другу не нужен белый IP и настройка роутера — просто передайте ему код.': '友人にはパブリック IP やルーターのセットアップは必要ありません。コードを送信するだけです。',
    'Остановить канал': 'トンネルを止めてください',
