    'Откройте мир для сети (Esc → «Открыть для сети…»), затем друг вводит этот код.': 'ワールドを LAN に開きます (Esc → "LAN に開く...")、友人がこのコードを入力します。',
    'В Minecraft: Сетевая игра → Прямое подключение → добавьте {a}': 'Minecraft の場合: マルチプレイヤー → 直接接続 → {a} を追加',
