    'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник и модель выбираются в окне «ИИ-сборка».': '制限: 選択する MOD の最大数 — 「パックに必要な数だけ」空のままにしておきます。ソースとモデルは AI パック ウィンドウで選択されます。',
    'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом. Модель — кто именно собирает сборку.': '制限を空のままにしておくと、パックに必要な数の MOD が追加されます。 「両方を一度に」は両方のカタログを検索します。優先されるものが最初に検索され、次にもう一方が検索されます。モデルは実際にパックを構築する人です。',
