    'Моды, конфиги и миры профиля скопируются в новый профиль лаунчера.': 'Модҳои профил, конфигуратсияҳо ва ҷаҳониён ба профили нави оғозкунанда нусхабардорӣ карда мешаванд.',
    'Ищу профили…': 'Дар ҷустуҷӯи профилҳо…',
