    'по сети: {a}': 'LAN аркылуу: {a}',
    'Сначала откройте мир для сети: в игре Esc → «Открыть для сети…».': 'Алгач LANга дүйнөнү ачыңыз: оюнда Esc → "LAN\'га ачуу..." баскычын басыңыз.',
    'Другу не нужен белый IP и настройка роутера — просто передайте ему код.': 'Сиздин досуңузга коомдук IP жана роутерди орнотуунун кереги жок — жөн гана кодду жөнөтүңүз.',
    'Остановить канал': 'Туннелди токтоткула',
