    'Через роутер (UPnP)': 'Маршрутизатор аркылуу (UPnP)',
    'Скопируйте вручную.': 'Аны кол менен көчүрүңүз.',
    'Введите код друга': 'Досуңуздун кодун киргизиңиз',
