    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Minimalus: žaidimas uždaromas kartu su paleidimo priemone. Standartinis: taip pat nėra mainų srities, nėra kitų langų, nėra rodymo nustatymų.',
    'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': 'Griežtas: taip pat žemas vientisumas – rašoma tik į profilio aplanką, visa kita – tik skaitoma. Negarantuoja, kad kiekvienas modas veiks.',
