    'Откройте папку игры и проверьте каталог crash-reports вручную.': 'Atveriet spēles mapi un manuāli pārbaudiet avāriju ziņojumu direktoriju.',
    'Запустите игру ещё раз — при новом падении отчёт появится здесь.': 'Sāciet spēli no jauna — ziņojums tiks parādīts šeit nākamajā avārijā.',
    'Посмотрите консоль лаунчера — ошибка могла остаться только в stderr.': 'Pārbaudiet palaišanas konsoli — kļūda var būt tikai stderr.',
    'Запустите игру снова: при новом падении появится crash-report.': 'Sāciet spēli vēlreiz: nākamajā avārijā tiks parādīts avārijas ziņojums.',
    'Откройте профиль → «Java и память» и поднимите верхний предел (например, 6144 МБ).': 'Atveriet profilu → "Java un atmiņa" un palieliniet augšējo robežu (piemēram, 6144 MB).',
    'Не ставьте больше ~70% всей оперативной памяти — станет только хуже.': 'Nepiešķiriet vairāk par ~70% no kopējās RAM — tas tikai pasliktinās situāciju.',
    'Проверьте, нет ли рядом тяжёлых сборок с сотнями модов.': 'Pārbaudiet, vai tuvumā nav citas smagas modifikācijas pakotnes ar simtiem modifikāciju.',
    'Чаще всего это драйвер видеокарты или мод с нативным кодом (шейдеры, рендер).': 'Visbiežāk tas ir GPU draiveris vai modifikācija ar vietējo kodu (ēnotāji, renderēšana).',
    'Обновите драйвер видеокарты.': 'Atjauniniet GPU draiveri.',
    'Уберите недавно добавленные моды и запустите снова.': 'Noņemiet nesen pievienotās modifikācijas un sāciet no jauna.',
    'Откройте профиль → «Java и память» и выберите версию: 1.16 и ниже — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.': 'Atveriet profilu → "Java un atmiņa" un izvēlieties versiju: ​​1.16 un jaunāku — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.',
    'Если Java нужной версии нет — скачайте её в настройках лаунчера.': 'Ja trūkst nepieciešamās Java versijas, lejupielādējiet to palaišanas programmas iestatījumos.',
    'Обновите драйвер видеокарты (NVIDIA/AMD/Intel).': 'Atjauniniet GPU draiveri (NVIDIA/AMD/Intel).',
