    'Уберите моды рендера/шейдеров, если падение началось после их установки.': 'Noņemiet renderēšanas/ēnotāju modifikācijas, ja avārija sākās pēc to instalēšanas.',
    'Прочитайте строки «requires … which is missing» в отчёте — там перечислено, чего не хватает.': 'Pārskatā izlasiet rindiņas "nepieciešams … kas trūkst" — tajās ir norādīts, kas trūkst.',
    'Установите недостающие моды или уберите лишние.': 'Instalējiet trūkstošos modifikācijas vai noņemiet papildu modifikācijas.',
    'Проверьте, что все моды одной версии Minecraft.': 'Pārliecinieties, vai visas modifikācijas ir paredzētas tai pašai Minecraft versijai.',
    'Обновите виновный мод до версии под ваш Minecraft.': 'Atjauniniet vainīgo modi uz sava Minecraft versiju.',
    'Уберите конфликтующий мод или его версию для другой сборки.': 'Noņemiet konfliktējošo modifikāciju vai tā versiju citai modpack pakotnei.',
