    '.mrpack — стандартный формат Modrinth (моды, конфиги, ресурспаки). .zip — папка сборки для ручной установки.': '.mrpack — standarta Modrinth formāts (modi, konfigurācijas, resursu pakotnes). .zip — modpack mape manuālai instalēšanai.',
