    'Проблема с модами: {mods}.': 'Мод мәселесі: {mods}.',
    'Mixin-патч не применился, вероятный виновник — {mod}.': 'Mixin патчі қолданылмады; ықтимал кінәлі {mod}.',
    'Mixin-патч не применился: мод несовместим с этой версией игры или другого мода.': 'Mixin патчын қолдану мүмкін болмады: мод осы ойынмен немесе басқа мод нұсқасымен үйлеспейді.',
    'Отчёт прямо указывает на мод.': 'Есеп тікелей режимге нұсқайды.',
    'Отчёт прямо указывает на мод. {error}': 'Есеп тікелей режимге нұсқайды. {error}',
    'Судя по стеку, ошибка пришла из {mod}.': 'Стек ізі {mod} белгісін көрсетеді.',
    '{error}\n\nСудя по стеку, ошибка пришла из {mod}.': '{error}\n\nСтек ізі {mod} белгісін көрсетеді.',
    'Точную причину определить не удалось — смотрите лог.': 'Нақты себебін анықтау мүмкін болмады — журналды тексеріңіз.',
    '{error}\n\nТочную причину определить не удалось — смотрите лог.': '{error}\n\nНақты себебін анықтау мүмкін болмады — журналды тексеріңіз.',
    'Откройте папку игры и проверьте каталог crash-reports вручную.': 'Ойын қалтасын ашыңыз және апат туралы есептер каталогын қолмен тексеріңіз.',
    'Запустите игру ещё раз — при новом падении отчёт появится здесь.': 'Ойынды қайта бастаңыз — есеп осы жерде келесі бұзылу кезінде пайда болады.',
    'Посмотрите консоль лаунчера — ошибка могла остаться только в stderr.': 'Іске қосу консолін тексеріңіз — қате тек stderr-де болуы мүмкін.',
    'Запустите игру снова: при новом падении появится crash-report.': 'Ойынды қайта бастаңыз: келесі бұзылу туралы қате туралы есеп пайда болады.',
    'Откройте профиль → «Java и память» и поднимите верхний предел (например, 6144 МБ).': 'Профильді ашыңыз → «Java және жад» және жоғарғы шекті көтеріңіз (мысалы, 6144 МБ).',
    'Не ставьте больше ~70% всей оперативной памяти — станет только хуже.': 'Жалпы жедел жадтың ~70%-дан астамын бөлмеңіз - бұл жағдайды нашарлатады.',
    'Проверьте, нет ли рядом тяжёлых сборок с сотнями модов.': 'Жақын жерде жүздеген модтары бар басқа ауыр модпакеттердің бар-жоғын тексеріңіз.',
    'Чаще всего это драйвер видеокарты или мод с нативным кодом (шейдеры, рендер).': 'Көбінесе бұл GPU драйвері немесе жергілікті коды бар мод (шейдерлер, рендеринг).',
    'Обновите драйвер видеокарты.': 'GPU драйверін жаңартыңыз.',
    'Уберите недавно добавленные моды и запустите снова.': 'Жақында қосылған режимдерді жойып, қайта бастаңыз.',
    'Откройте профиль → «Java и память» и выберите версию: 1.16 и ниже — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.': 'Профильді ашыңыз → «Java және жад» және нұсқасын таңдаңыз: 1.16 және одан төмен — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.',
    'Если Java нужной версии нет — скачайте её в настройках лаунчера.': 'Қажетті Java нұсқасы жоқ болса, оны іске қосу құралының параметрлерінен жүктеп алыңыз.',
    'Обновите драйвер видеокарты (NVIDIA/AMD/Intel).': 'GPU драйверін жаңартыңыз (NVIDIA/AMD/Intel).',
    'Проверьте, что видеокарта не отключена и игра не запущена в режиме удалённого рабочего стола.': 'GPU қосулы екенін және ойын қашықтағы жұмыс үстелінде жұмыс істемейтінін тексеріңіз.',
    'Уберите моды рендера/шейдеров, если падение началось после их установки.': 'Рендеринг/шейдер режимдерін орнатқаннан кейін апат басталса, алып тастаңыз.',
    'Прочитайте строки «requires … which is missing» в отчёте — там перечислено, чего не хватает.': 'Есептегі «қажет ... жоқ» жолдарын оқыңыз — оларда не жетіспейтінін тізімдейді.',
    'Установите недостающие моды или уберите лишние.': 'Жетіспейтін режимдерді орнатыңыз немесе қосымшаларын алып тастаңыз.',
    'Проверьте, что все моды одной версии Minecraft.': 'Барлық модификациялар бірдей Minecraft нұсқасына арналғанына көз жеткізіңіз.',
    'Обновите виновный мод до версии под ваш Minecraft.': 'Кінәлі режимін Minecraft нұсқасына жаңартыңыз.',
    'Уберите конфликтующий мод или его версию для другой сборки.': 'Басқа модпакет үшін қайшылықты режимді немесе оның нұсқасын жойыңыз.',
    'Обновите или удалите виновный мод.': 'Кінәлі режимін жаңартыңыз немесе жойыңыз.',
    'Проверьте, что его версия совпадает с версией Minecraft.': 'Оның нұсқасы Minecraft нұсқасына сәйкес келетініне көз жеткізіңіз.',
    'Обновите виновный мод или удалите его и проверьте запуск.': 'Кінәлі режимін жаңартыңыз немесе оны жойыңыз және іске қосуды тексеріңіз.',
    'Если не помогло — отключите моды по половине, чтобы найти конфликт.': 'Егер бұл көмектеспесе, қайшылықты табу үшін модульдерді екіге бөліңіз.',
    'Откройте отчёт и посмотрите блок «Caused by» — там обычно указан мод.': 'Есепті ашыңыз және «Себебі» блогын тексеріңіз — ол әдетте режимді атайды.',
    'Отключите половину модов и запустите: так конфликт находится быстрее всего.': 'Модтардың жартысын өшіріп, іске қосыңыз: бұл қақтығысты ең жылдам табады.',
