    'Стандартная: запрет на буфер обмена, чужие окна и настройки экрана. Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение.': 'სტანდარტული: ბუფერში, სხვა ფანჯრების გარეშე, ეკრანის პარამეტრების გარეშე. მკაცრი: ასევე დაბალი მთლიანობა — ჩაწერა მხოლოდ პროფილის საქაღალდეში, დანარჩენი ყველაფერი მხოლოდ წასაკითხად.',
    'Не гарантирует работу всех модов.': 'არ იძლევა გარანტიას, რომ ყველა რეჟიმი იმუშავებს.',
