    'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'მინიმალური: თამაში იხურება გამშვებთან ერთად. სტანდარტული: ასევე არ არის ბუფერში, არც სხვა ფანჯრები, არც ეკრანის პარამეტრები.',
