    'Импорт из Modrinth App': 'იმპორტი Modrinth აპლიკაციიდან',
    'Моды, конфиги и миры профиля скопируются в новый профиль лаунчера.': 'პროფილის მოდიფიკაციები, კონფიგურაციები და სამყაროები დაკოპირდება გამშვების ახალ პროფილში.',
