    'Не нашлись в каталоге: {list}': 'კატალოგში არ მოიძებნა: {list}',
    'Создать профиль и поставить {n}': 'შექმენით პროფილი და დააინსტალირეთ {n}',
    'Ставлю сборку…': 'მიმდინარეობს პაკეტის ინსტალაცია…',
    'Не установились:': 'ინსტალაცია ვერ მოხერხდა:',
