    'Опишите сборку хотя бы одним предложением': 'ᓇᓗᓇᐃᔭᕐᓗᒍ ᐴᖅᑲᖅᓯᒪᔪᖅ ᐊᑕᐅᓯᕐᒥᒃ ᐅᖃᐅᓯᖅᑕᖃᕐᓗᓂ',
